package com.microsoft.kiota;

import static org.junit.jupiter.api.Assertions.assertNotNull;
import static org.junit.jupiter.api.Assertions.assertNull;
import static org.junit.jupiter.api.Assertions.assertThrows;
import static org.junit.jupiter.api.Assertions.assertTrue;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.verify;

import com.microsoft.kiota.serialization.SerializationWriter;

import org.junit.jupiter.api.Test;

class MultiPartBodyTest {
    private static <T> T nullValue() {
        return java.util.Collections.<String, T>emptyMap().get("missing");
    }

    @Test
    void defensive() {
        final MultipartBody multipartBody = new MultipartBody();
        assertThrows(
                IllegalArgumentException.class,
                () -> multipartBody.addOrReplacePart(nullValue(), "foo", "bar"));
        assertThrows(
                IllegalArgumentException.class,
                () -> multipartBody.addOrReplacePart("foo", nullValue(), "bar"));
        assertThrows(
                NullPointerException.class,
                () -> multipartBody.addOrReplacePart("foo", "bar", nullValue()));
        assertThrows(IllegalArgumentException.class, () -> multipartBody.getPartValue(nullValue()));
        assertThrows(IllegalArgumentException.class, () -> multipartBody.removePart(nullValue()));
        assertThrows(NullPointerException.class, () -> multipartBody.serialize(nullValue()));
        assertThrows(
                UnsupportedOperationException.class, () -> multipartBody.getFieldDeserializers());
    }

    @Test
    void requiresRequestAdapter() {
        final MultipartBody multipartBody = new MultipartBody();
        final SerializationWriter writer = mock(SerializationWriter.class);
        assertThrows(IllegalStateException.class, () -> multipartBody.serialize(writer));
    }

    @Test
    void requiresPartsForSerialization() {
        final MultipartBody multipartBody = new MultipartBody();
        final SerializationWriter writer = mock(SerializationWriter.class);
        final RequestAdapter requestAdapter = mock(RequestAdapter.class);
        multipartBody.requestAdapter = requestAdapter;
        assertThrows(IllegalStateException.class, () -> multipartBody.serialize(writer));
    }

    @Test
    void addsPart() {
        final MultipartBody multipartBody = new MultipartBody();
        final RequestAdapter requestAdapter = mock(RequestAdapter.class);
        multipartBody.requestAdapter = requestAdapter;
        multipartBody.addOrReplacePart("foo", "bar", "baz");
        final Object result = multipartBody.getPartValue("foo");
        assertNotNull(result);
        assertTrue(result instanceof String);
    }

    @Test
    void removesPart() {
        final MultipartBody multipartBody = new MultipartBody();
        final RequestAdapter requestAdapter = mock(RequestAdapter.class);
        multipartBody.requestAdapter = requestAdapter;
        multipartBody.addOrReplacePart("foo", "bar", "baz");
        multipartBody.removePart("FOO");
        final Object result = multipartBody.getPartValue("foo");
        assertNull(result);
    }

    @Test
    void notAddFilename() {
        final MultipartBody multipartBody = new MultipartBody();
        final SerializationWriter writer = mock(SerializationWriter.class);
        multipartBody.requestAdapter = mock(RequestAdapter.class);
        multipartBody.addOrReplacePart("foo", "bar", "baz");
        multipartBody.serialize(writer);
        verify(writer).writeStringValue("Content-Disposition", "form-data; name=\"foo\"");
    }

    @Test
    void addFilename() {
        final MultipartBody multipartBody = new MultipartBody();
        final SerializationWriter writer = mock(SerializationWriter.class);
        multipartBody.requestAdapter = mock(RequestAdapter.class);
        multipartBody.addOrReplacePart("foo", "bar", "baz", "image.png");
        multipartBody.serialize(writer);
        verify(writer)
                .writeStringValue(
                        "Content-Disposition", "form-data; name=\"foo\"; filename=\"image.png\"");
    }
    // serialize method is being tested in the serialization library
}
